mapper.select:
SELECT B.BOARDNUM, B.TITLE, B.CONTENT, B.REGDATE, M.STUDENTID, M.NAME, C.CLUBNUM, C.CLUBNAME
FROM CLUBBOARD B JOIN MEMBER M ON B.STUDENTID = M.STUDENTID JOIN CLUB C ON C.CLUBNUM = B.CLUBNUM
WHERE BOARDNUM = #{boardNum}

mapper.delete:
DELETE FROM BOARDFILE
WHERE BOARDNUM IN (
SELECT BOARDNUM
FROM CLUBBOARD
WHERE STUDENTID = #{studentId}
)

mapper.select:
		SELECT  FILENUM, REGEXP_REPLACE(TITLE, '^.*/[sb]_[^_]+_', '') AS TITLE, REGDATE, TITLE AS FILES, BOARDNUM
 	FROM BOARDFILE
 	WHERE BOARDNUM = #{boardNum}
